export const NOUNS = NOUN_ROWS.map(([nom, g, an, cls, pr, sg, pl]) => ({ nom, g, an: Boolean(an), cls, pr, sg: sg.split(' '), pl: pl ? pl.split(' ') : null }));
const byCls = (...cls) => NOUNS.filter((n) => cls.includes(n.cls));
const noun = (nom) => NOUNS.find((n) => n.nom === nom);

/** Три разных неверных варианта из списка кандидатов (не совпадают с ответом). */
function three(ok, cands) {
  const out = [];
  for (const c of cands) if (c && c !== ok && !out.includes(c) && out.length < 3) out.push(c);
  return out.length === 3 ? out : null;
}
const rot = (arr, k) => arr.map((_, i) => arr[(i + k) % arr.length]);
const cap = (s) => s[0].toUpperCase() + s.slice(1);
/** Строка задания: предложение «...______ (подсказка)...», ответ, неверные, разбор. */
function row(level, sentence, ok, cands, ex) {
  const wrong = three(ok, cands);
  return wrong ? [level, sentence, ok, wrong, ex] : null;
}
const full = (sentence, ok) => sentence.replace(/______( \([^)]*\))?/, ok);
/** Разбор «правило: полное предложение». */
const why = (rule, sentence, ok, tail = L('', '', '')) =>
  L(`${rule.en}: «${full(sentence, ok)}»${tail.en}`, `${rule.ru}: «${full(sentence, ok)}»${tail.ru}`, `${rule.kk}: «${full(sentence, ok)}»${tail.kk}`);
/** Ограничивает число заданий одного вида: берёт равномерно по списку. */
function spread(rows, max) {
  const ok = rows.filter(Boolean);
  if (ok.length <= max) return ok;
  return Array.from({ length: max }, (_, i) => ok[Math.floor((i * ok.length) / max)]);
}

// ---------- A1: где? что? мой / моя, прилагательные ----------
const PLACE_RULE = L('Where? After в / на (location) use the prepositional case', 'Где? О месте после «в» или «на» - предложный падеж', 'Қайда? Орынды білдіретін «в» / «на» предлогынан кейін жатыс септік (предложный) керек');
const II_NOTE = L('. Words in -ия and -ие take the ending -и.', '. Слова на -ия и -ие получают окончание -и.', '. -ия, -ие деп аяқталатын сөздер -и жалғауын алады.');
const PLACE_SUBJ = ['Я сейчас', 'Мы сейчас', 'Мой брат сейчас', 'Анна сейчас', 'Наши друзья сейчас'];
const placeRows = [
  ...byCls('pl', 'e').map((n, i) => {
    const s = `${PLACE_SUBJ[i % 5]} ${n.pr} ______ (${n.nom}).`;
    return row(1, s, n.sg[5], rot(n.sg, i), why(PLACE_RULE, s, n.sg[5], /ии$/.test(n.sg[5]) ? II_NOTE : L('.', '.', '.')));
  }),
  ...byCls('geo').flatMap((n, i) => ['Я живу в ______', 'Мой друг учится в ______'].map((start, k) => {
    const s = `${start} (${n.nom}).`;
    return row(1, s, n.sg[5], rot(n.sg, i + k), why(PLACE_RULE, s, n.sg[5], /ии$/.test(n.sg[5]) ? II_NOTE : L('.', '.', '.')));
  })),
];

const OBJ_VERB = { книга: 'читаю', газета: 'читаю', журнал: 'читаю', письмо: 'пишу', задание: 'делаю', словарь: 'беру', тетрадь: 'покупаю', ручка: 'беру', билет: 'покупаю', машина: 'вижу', телефон: 'ищу', яблоко: 'ем', окно: 'открываю', молоко: 'пью', вода: 'пью', сок: 'пью', чай: 'пью', рыба: 'ем', суп: 'ем', мясо: 'ем', хлеб: 'покупаю' };
const ACC_RULE = L('What? The direct object of a verb is in the accusative case', 'Что? Прямое дополнение после глагола - винительный падеж', 'Нені? Етістіктен кейінгі тура толықтауыш табыс септікте (винительный) тұрады');
const accNote = (n) =>
  n.g === 'f'
    ? n.nom.endsWith('ь')
      ? L('. Feminine nouns in -ь do not change.', '. Слова женского рода на -ь не меняются.', '. -ь деп аяқталатын әйел тектес сөздер өзгермейді.')
      : L('. Feminine nouns: -а → -у, -я → -ю.', '. Женский род: -а → -у, -я → -ю.', '. Әйел тегі: -а → -у, -я → -ю.')
    : L('. Inanimate masculine and neuter nouns keep the nominative form.', '. Неодушевлённые слова мужского и среднего рода не меняются.', '. Жансыз еркек және орта тектес сөздер өзгермейді.');
const accRows = Object.entries(OBJ_VERB).map(([nom, verb], i) => {
  const n = noun(nom);
  const s = `Я ${verb} ______ (${nom}).`;
  return row(1, s, n.sg[3], rot(n.sg, i), why(ACC_RULE, s, n.sg[3], accNote(n)));
});

const POSS = { мой: ['мой', 'моя', 'моё', 'мои'], твой: ['твой', 'твоя', 'твоё', 'твои'], наш: ['наш', 'наша', 'наше', 'наши'], ваш: ['ваш', 'ваша', 'ваше', 'ваши'] };
const GI = { m: 0, f: 1, n: 2, pl: 3 };
const LOOKS_F = new Set(['папа', 'дедушка']);
function agreeEx(n, g, word, form) {
  const odd = LOOKS_F.has(n.nom);
  const nn = g === 'pl' ? n.pl[0] : n.nom;
  return L(
    `"${nn}" is ${GENDER[g].en}, so ${word} → ${form}: ${form} ${nn}.${odd ? ` ${n.nom} ends in -а but means a man, so it is masculine.` : ''}`,
    `«${nn}» - ${GENDER[g].ru}, поэтому ${word} → ${form}: ${form} ${nn}.${odd ? ` Слово «${n.nom}» оканчивается на -а, но называет мужчину, поэтому оно мужского рода.` : ''}`,
    `«${nn}» - ${GENDER[g].kk}, сондықтан ${word} → ${form}: ${form} ${nn}.${odd ? ` «${n.nom}» сөзі -а әрпімен аяқталады, бірақ ер адамды білдіреді, сондықтан еркек тектес.` : ''}`,
  );
}
const possRows = spread(
  NOUNS.filter((n) => !['geo', 'food'].includes(n.cls)).flatMap((n, i) => {
    const word = Object.keys(POSS)[i % 4];
    const forms = POSS[word];
    const out = [[n.nom, n.g]];
    if (n.pl && i % 3 === 0) out.push([n.pl[0], 'pl']);
    return out.map(([w, g]) => [1, `Это ______ (${word}) ${w}.`, forms[GI[g]], forms.filter((f) => f !== forms[GI[g]]), agreeEx(n, g, word, forms[GI[g]])]);
  }),
  34,
);

// Прилагательные с твёрдой основой: новый, новая, новое, новые.
const ADJ = [
  ['нов', ['p', 'pl', 't', 'e']],
  ['стар', ['p', 'pl', 't']],
  ['красив', ['p', 'pl', 't']],
  ['интересн', ['pl', 't', 'e']],
  ['добр', ['p', 'job']],
  ['умн', ['p', 'job']],
  ['бел', ['t']],
  ['трудн', ['e']],
];
const END = {
  m: ['ый', 'ого', 'ому', 'ый', 'ым', 'ом'],
  f: ['ая', 'ой', 'ой', 'ую', 'ой', 'ой'],
  n: ['ое', 'ого', 'ому', 'ое', 'ым', 'ом'],
  pl: ['ые', 'ых', 'ым', 'ые', 'ыми', 'ых'],
};
/** Форма прилагательного: основа, род (m/f/n/pl), падеж, одушевлённость (для винительного). */
const adjForm = (stem, g, c, an = false) => stem + (c === 3 && an && (g === 'm' || g === 'pl') ? END[g][1] : END[g][c]);
const ADJ_SKIP = new Set(['почта', 'работа', 'улица', 'общежитие', 'стол', 'окно', 'тетрадь']);
const adjFor = (n, i, avoidVowel = false) => {
  const list = ADJ.filter(([stem, cls]) => cls.includes(n.cls) && !(avoidVowel && /^[аеиоуэ]/.test(stem)));
  return list.length ? list[i % list.length][0] : null;
};
const adjNomRows = spread(
  NOUNS.filter((n) => !['geo', 'food'].includes(n.cls) && !ADJ_SKIP.has(n.nom)).flatMap((n, i) => {
    const stem = adjFor(n, i);
    if (!stem) return [];
    const forms = ['m', 'f', 'n', 'pl'].map((g) => adjForm(stem, g, 0));
    const list = [[n.nom, n.g]];
    if (n.pl && i % 4 === 1) list.push([n.pl[0], 'pl']);
    return list.map(([w, g]) => [1, `У нас ______ (${stem}ый) ${w}.`, forms[GI[g]], forms.filter((f) => f !== forms[GI[g]]), agreeEx(n, g, `${stem}ый`, forms[GI[g]])]);
  }),
  34,
);

// ---------- A2: падежи с предлогами, глаголы движения ----------
const caseRow = (level, s, n, c, rule, tail, k, forms = n.sg) => row(level, s, forms[c], rot(n.sg, k), why(rule, s, forms[c], tail));
const DOT = L('.', '.', '.');
const ANIM_RULE = L('Whom? After ждать, знать, любить use the accusative case', 'Кого? После «ждать», «знать», «любить» - винительный падеж', 'Кімді? «Ждать», «знать», «любить» етістіктерінен кейін табыс септік (винительный) керек');
const animNote = (n) =>
  n.g === 'm' && !/[ая]$/.test(n.nom)
    ? L('. Animate masculine nouns take the genitive form: -а / -я.', '. У одушевлённых слов мужского рода форма как в родительном: -а / -я.', '. Жанды еркек тектес сөздердің формасы ілік септіктегідей: -а / -я.')
    : L('. Nouns in -а / -я: -у / -ю.', '. Слова на -а / -я: -у / -ю.', '. -а / -я деп аяқталатын сөздер: -у / -ю.');
const people = byCls('p');
const jobs = byCls('job');
const animRows = people.flatMap((n, i) => {
  const s = `Я ${['жду', 'хорошо знаю', 'очень люблю'][i % 3]} ______ (${n.nom}).`;
  return [caseRow(2, s, n, 3, ANIM_RULE, animNote(n), i)];
});
const NET_RULE = L('After нет (there is no ...) use the genitive case', 'Нет кого? чего? После «нет» - родительный падеж', '«Нет» (жоқ) сөзінен кейін ілік септік (родительный) керек');
const netRows = [...byCls('t'), ...people.slice(0, 6), noun('сахар'), noun('хлеб')].map((n, i) => {
  const s = `У меня нет ______ (${n.nom}).`;
  return n.sg.filter((f) => f !== n.sg[1]).length >= 3 && new Set(n.sg).size >= 4 ? caseRow(2, s, n, 1, NET_RULE, DOT, i) : null;
});
const U_RULE = L('у + genitive: "at someone\'s place"', 'у кого? Предлог «у» требует родительного падежа', '«У» предлогы (кімде?) ілік септікті (родительный) талап етеді');
const uRows = [...people, ...jobs].map((n, i) => caseRow(2, `Вчера я был у ______ (${n.nom}).`, n, 1, U_RULE, DOT, i));
const DAT_RULE = L('To whom? звонить, помогать, дарить + dative case', 'Кому? После «звонить», «помогать», «подарить» - дательный падеж', 'Кімге? «Звонить», «помогать», «подарить» етістіктерінен кейін барыс септік (дательный) керек');
const datRows = [...people, ...jobs.slice(0, 3)].map((n, i) => caseRow(2, `${['Я часто звоню', 'Я всегда помогаю', 'Я подарил книгу'][i % 3]} ______ (${n.nom}).`, n, 2, DAT_RULE, DOT, i));
const S_RULE = L('с (with, together with) + instrumental case', 'С кем? с чем? Предлог «с» (вместе) - творительный падеж', 'Кіммен? немен? «С» (бірге) предлогынан кейін көмектес септік (творительный) керек');
const sRows = [
  ...people.map((n, i) => caseRow(2, `Я гуляю в парке с ______ (${n.nom}).`, n, 4, S_RULE, DOT, i)),
  ...['лимон', 'сахар', 'молоко'].map((w, i) => caseRow(2, `Я пью чай с ______ (${w}).`, noun(w), 4, S_RULE, DOT, i)),
];
const JOB_RULE = L('стать / работать + instrumental case (as whom?)', 'Кем? После «стать», «работать» - творительный падеж', 'Кім болып? «Стать», «работать» етістіктерінен кейін көмектес септік (творительный) керек');
const jobRows = jobs.flatMap((n, i) => [`Мой брат хочет стать ______ (${n.nom}).`, `Моя сестра работает ______ (${n.nom}).`].map((s, k) => caseRow(2, s, n, 4, JOB_RULE, DOT, i + k)));
const KUDA_RULE = L('Where to? в / на + accusative case (direction)', 'Куда? Направление: «в» / «на» + винительный падеж', 'Қайда (бағыт)? «В» / «на» + табыс септік (винительный)');
const kudaRows = byCls('pl', 'e').map((n, i) => caseRow(2, `Завтра мы пойдём ${n.pr} ______ (${n.nom}).`, n, 3, KUDA_RULE, L('. Compare: где? - в / на + prepositional.', '. Сравни: где? - «в» / «на» + предложный.', '. Салыстыр: қайда (орын)? - «в» / «на» + предложный.'), i));

// Глаголы движения: идти / ходить, ехать / ездить.
const MOTION = {
  идти: ['иду', 'идёшь', 'идёт', 'идём', 'идёте', 'идут'],
  ходить: ['хожу', 'ходишь', 'ходит', 'ходим', 'ходите', 'ходят'],
  ехать: ['еду', 'едешь', 'едет', 'едем', 'едете', 'едут'],
  ездить: ['езжу', 'ездишь', 'ездит', 'ездим', 'ездите', 'ездят'],
};
const SUBJ = [['я'], ['ты'], ['он', 'она', 'Анна', 'мой брат'], ['мы'], ['вы'], ['они', 'мои друзья', 'студенты']];
const MOTION_FRAMES = [
  ['идти', (s, d) => `Сейчас ${s} ______ ${d} пешком.`, L('Right now, in one direction, on foot - идти', 'Сейчас, в одном направлении, пешком - глагол «идти»', 'Қазір, бір бағытта, жаяу - «идти» етістігі')],
  ['ходить', (s, d) => `Каждый день ${s} ______ ${d} пешком.`, L('Regularly, there and back, on foot - ходить', 'Регулярно, туда и обратно, пешком - глагол «ходить»', 'Үнемі, барып-қайтып, жаяу - «ходить» етістігі')],
  ['ехать', (s, d) => `Сейчас ${s} ______ ${d} на автобусе.`, L('Right now, in one direction, by transport - ехать', 'Сейчас, в одном направлении, на транспорте - глагол «ехать»', 'Қазір, бір бағытта, көлікпен - «ехать» етістігі')],
  ['ездить', (s, d) => `Каждую субботу ${s} ______ ${d} на машине.`, L('Regularly, there and back, by transport - ездить', 'Регулярно, туда и обратно, на транспорте - глагол «ездить»', 'Үнемі, барып-қайтып, көлікпен - «ездить» етістігі')],
];
const DEST = byCls('pl').filter((n) => !['комната', 'аудитория', 'улица', 'озеро', 'общежитие'].includes(n.nom));
const motionRows = [];
for (let i = 0; i < 56; i++) {
  const [verb, frame, rule] = MOTION_FRAMES[i % 4];
  const p = Math.floor(i / 4) % 6;
  const subj = SUBJ[p][Math.floor(i / 24) % SUBJ[p].length];
  const d = DEST[(i * 5) % DEST.length];
  const s = frame(subj, `${d.pr} ${d.sg[3]}`);
  const ok = MOTION[verb][p];
  motionRows.push(row(2, s, ok, Object.keys(MOTION).map((v) => MOTION[v][p]), why(rule, s, ok, DOT)));
}

// ---------- B1: числа, прилагательное + существительное в падежах ----------
const NUM_FEW = { m: ['два', 'три', 'четыре'], n: ['два', 'три', 'четыре'], f: ['две', 'три', 'четыре'] };
const NUM_MANY = ['пять', 'шесть', 'семь', 'восемь', 'десять', 'двенадцать'];
const NUM_ONE = { m: 'двадцать один', f: 'двадцать одна', n: 'двадцать одно' };
const NUM_RULE = {
  few: L('After 2, 3, 4 (два / две, три, четыре) the noun is in the genitive singular', 'После «два (две), три, четыре» - родительный падеж единственного числа', '«Два (две), три, четыре» сандарынан кейін зат есім ілік септіктің жекеше түрінде тұрады'),
  many: L('From 5 upwards (пять, шесть...) the noun is in the genitive plural', 'После «пять» и больших чисел - родительный падеж множественного числа', '«Пять» және одан үлкен сандардан кейін зат есім ілік септіктің көпше түрінде тұрады'),
  one: L('A number ending in "one" (21, 31, 101) takes the nominative singular', 'Если число оканчивается на «один» (21, 31, 101), существительное стоит в именительном падеже единственного числа', 'Сан «один» сөзімен аяқталса (21, 31, 101), зат есім атау септіктің жекеше түрінде тұрады'),
};
const NUM_FRAME = { p: 'В зале', pl: 'В нашем городе', t: 'На столе' };
const numRows = [...people.filter((n) => n.nom !== 'мама' && n.nom !== 'папа'), ...byCls('pl').filter((n) => ['театр', 'музей', 'парк', 'магазин', 'банк', 'школа', 'библиотека', 'университет', 'рынок', 'стадион'].includes(n.nom)), ...byCls('t').filter((n) => n.nom !== 'стол' && n.nom !== 'окно')].flatMap((n, i) => {
  const where = NUM_FRAME[n.cls];
  const cands = [n.sg[0], n.sg[1], n.pl[1], n.pl[0], n.sg[4], n.pl[2]];
  const out = [];
  const few = NUM_FEW[n.g][i % 3];
  let s = `${where} ${few} ______ (${n.nom}).`;
  out.push(row(3, s, n.sg[1], cands, why(NUM_RULE.few, s, n.sg[1], DOT)));
  s = `${where} ${NUM_MANY[i % NUM_MANY.length]} ______ (${n.nom}).`;
  out.push(row(3, s, n.pl[1], cands, why(NUM_RULE.many, s, n.pl[1], DOT)));
  if (i % 3 === 0) {
    s = `${where} ${NUM_ONE[n.g]} ______ (${n.nom}).`;
    out.push(row(3, s, n.sg[0], cands, why(NUM_RULE.one, s, n.sg[0], DOT)));
  }
  return out;
});

/** Прилагательное + существительное: прилагательное согласуется в роде, числе и падеже. */
function adjCaseEx(n, stem, g, c, form, nounForm) {
  const anim = c === 3 && n.an && g === 'm';
  return L(
    `"${n.nom}" is ${GENDER[g].en}, ${CASE[c].en} case: ${stem}ый → ${form} ${nounForm}.${anim ? ' Animate masculine: accusative = genitive.' : ''}`,
    `«${n.nom}» - ${GENDER[g].ru}, ${CASE[c].ru} падеж: ${stem}ый → ${form} ${nounForm}.${anim ? ' Одушевлённое слово мужского рода: винительный = родительный.' : ''}`,
    `«${n.nom}» - ${GENDER[g].kk}, ${CASE[c].kk}: ${stem}ый → ${form} ${nounForm}.${anim ? ' Жанды еркек тектес сөз: табыс септік = ілік септік.' : ''}`,
  );
}
function adjCaseRow(level, n, stem, c, frame) {
  const g = n.g;
  const ok = adjForm(stem, g, c, n.an);
  const others = [0, 1, 2, 3, 4, 5].filter((k) => k !== c);
  const cands = [...others.map((k) => adjForm(stem, g, k, n.an)), ...['m', 'f', 'n'].filter((x) => x !== g).map((x) => adjForm(stem, x, c, n.an))];
  const nf = n.sg[c];
  const s = frame(`______ (${stem}ый) ${nf}`);
  return row(level, s, ok, rot(cands, n.nom.length), adjCaseEx(n, stem, g, c, ok, nf));
}
const ADJ_FRAMES = {
  pl: [[5, (x, n) => `Мы были ${n.pr} ${x}.`], [1, (x) => `Здесь нет ${x}.`], [2, (x) => `Мы подошли к ${x}.`], [3, (x) => `Я вижу ${x}.`], [4, (x) => `Мы встретились рядом с ${x}.`]],
  p: [[5, (x) => `Мы говорили о ${x}.`], [2, (x) => `Мы подошли к ${x}.`], [3, (x) => `Я давно знаю ${x}.`], [4, (x) => `Я познакомился с ${x}.`], [1, (x) => `Это книга ${x}.`]],
  t: [[5, (x) => `Мы говорили о ${x}.`], [1, (x) => `Здесь нет ${x}.`], [3, (x) => `Я вижу ${x}.`], [4, (x) => `Я доволен ${x}.`]],
};
const adjCaseRows = spread(
  [...byCls('pl'), ...people, ...byCls('t')].filter((n) => !ADJ_SKIP.has(n.nom)).flatMap((n, i) => {
    const frames = ADJ_FRAMES[n.cls];
    return [0, 1].map((k) => {
      const [c, f] = frames[(i + k * 2) % frames.length];
      const stem = adjFor(n, i + k, c === 5);
      return stem ? adjCaseRow(3, n, stem, c, (x) => f(x, n)) : null;
    });
  }),
  44,
);

// ---------- B2: множественное число в падежах, «который» ----------
const PL_RULE = (c) => L(`plural, ${CASE[c].en} case`, `множественное число, ${CASE[c].ru} падеж`, `көпше түр, ${CASE[c].kk}`);
function plRow(n, c, s, k) {
  const ok = n.pl[c];
  const cands = rot([...n.pl, n.sg[c], n.sg[0]], k);
  const r = PL_RULE(c);
  return row(4, s, ok, cands, L(`${cap(r.en)}: ${n.nom} → ${ok}. «${full(s, ok)}»`, `${cap(r.ru)}: ${n.nom} → ${ok}. «${full(s, ok)}»`, `${cap(r.kk)}: ${n.nom} → ${ok}. «${full(s, ok)}»`));
}
const PL_PEOPLE = [[1, (w) => `У меня много ______ (${w}).`], [2, (w) => `Я часто пишу своим ______ (${w}).`], [3, (w) => `Я давно не видел своих ______ (${w}).`], [4, (w) => `Мы гуляли с нашими ______ (${w}).`], [5, (w) => `Он часто рассказывает о своих ______ (${w}).`]];
const PL_THINGS = [[1, (w) => `Я купил пять ______ (${w}).`], [5, (w) => `В этих ______ (${w}) много интересного.`], [4, (w) => `Он пришёл с новыми ______ (${w}).`]];
const plRows = spread(
  [
    ...[...people, ...jobs].flatMap((n, i) => [0, 2].map((k) => { const [c, f] = PL_PEOPLE[(i + k) % 5]; return plRow(n, c, f(n.nom), i + k); })),
    ...byCls('t').filter((n) => !['окно', 'машина', 'стол'].includes(n.nom)).flatMap((n, i) => [0, 1].map((k) => { const [c, f] = PL_THINGS[(i + k) % 3]; return plRow(n, c, f(n.nom), i + k); })),
    ...byCls('e').map((n, i) => plRow(n, 2, `Студенты готовятся к ______ (${n.nom}).`, i)),
  ],
  44,
);

const KOT = {
  m: ['который', 'которого', 'которому', 'которого', 'которым', 'котором'],
  f: ['которая', 'которой', 'которой', 'которую', 'которой', 'которой'],
  pl: ['которые', 'которых', 'которым', 'которых', 'которыми', 'которых'],
};
const KOT_ANTE = [['Это мой друг', 'друг', 'm'], ['Это моя подруга', 'подруга', 'f'], ['Это мои соседи', 'соседи', 'pl'], ['Это наш преподаватель', 'преподаватель', 'm'], ['Это моя сестра', 'сестра', 'f'], ['Это наши студенты', 'студенты', 'pl']];
const KOT_FRAMES = [
  [0, ', ______ живёт в Москве.', L('who lives? - nominative', 'кто живёт? - именительный падеж', 'кім тұрады? - атау септік')],
  [1, ', у ______ есть машина.', L('у кого? - genitive', 'у кого? - родительный падеж', 'кімде? - ілік септік')],
  [2, ', ______ я звонил вчера.', L('called whom? (dative) - dative', 'звонил кому? - дательный падеж', 'кімге қоңырау шалдым? - барыс септік')],
  [3, ', ______ я встретил в метро.', L('met whom? - accusative', 'встретил кого? - винительный падеж', 'кімді кездестірдім? - табыс септік')],
  [4, ', с ______ я учусь.', L('with whom? - instrumental', 'с кем? - творительный падеж', 'кіммен? - көмектес септік')],
  [5, ', о ______ я тебе рассказывал.', L('about whom? - prepositional', 'о ком? - предложный падеж', 'кім туралы? - жатыс септік')],
];
const kotRows = KOT_ANTE.flatMap(([ante, word, g], a) =>
  KOT_FRAMES.map(([c, tail, q], k) => {
    const s = `${ante}${tail}`;
    const ok = KOT[g][c];
    const cands = rot([...KOT[g], ...['m', 'f', 'pl'].filter((x) => x !== g).map((x) => KOT[x][c])], a + k);
    const gn = GENDER[g];
    return row(4, s, ok, cands, L(
      `который takes gender and number from "${word}" (${gn.en}) and its case from its own clause: ${q.en} → ${ok}.`,
      `«Который» берёт род и число от слова «${word}» (${gn.ru}), а падеж - от своей части предложения: ${q.ru} → ${ok}.`,
      `«Который» тек пен санды «${word}» сөзінен (${gn.kk}), ал септікті өз бөлігінен алады: ${q.kk} → ${ok}.`,
    ));
  }),
);

// ---------- C1: причастия и деепричастия ----------
// [НСВ, СВ, действ. наст., действ. прош., страд. прош., деепричастие СВ, дополнение, предложение со страдательным причастием]
const PART = [
  ['писать', 'написать', 'пишущий', 'написавший', 'написанный', 'написав', 'статью', 'Роман, ______ (написать) в прошлом веке, до сих пор популярен.'],
  ['читать', 'прочитать', 'читающий', 'прочитавший', 'прочитанный', 'прочитав', 'книгу', 'Текст, ______ (прочитать) на уроке, был очень трудным.'],
  ['решать', 'решить', 'решающий', 'решивший', 'решённый', 'решив', 'задачу', 'Вопрос, ______ (решить) на собрании, больше не обсуждается.'],
  ['строить', 'построить', 'строящий', 'построивший', 'построенный', 'построив', 'дом', 'Мост, ______ (построить) в прошлом году, украсил город.'],
  ['открывать', 'открыть', 'открывающий', 'открывший', 'открытый', 'открыв', 'окно', 'Магазин, ______ (открыть) на нашей улице, работает круглосуточно.'],
  ['получать', 'получить', 'получающий', 'получивший', 'полученный', 'получив', 'письмо', 'Ответ, ______ (получить) от компании, нас обрадовал.'],
  ['готовить', 'подготовить', 'готовящий', 'подготовивший', 'подготовленный', 'подготовив', 'доклад', 'Проект, ______ (подготовить) студентами, занял первое место.'],
  ['создавать', 'создать', 'создающий', 'создавший', 'созданный', 'создав', 'компанию', 'Фонд, ______ (создать) в 2010 году, помогает детям.'],
  ['изучать', 'изучить', 'изучающий', 'изучивший', 'изученный', 'изучив', 'материал', 'Материал, ______ (изучить) на прошлой неделе, будет на экзамене.'],
  ['выполнять', 'выполнить', 'выполняющий', 'выполнивший', 'выполненный', 'выполнив', 'задание', 'План, ______ (выполнить) досрочно, принёс компании прибыль.'],
  ['проверять', 'проверить', 'проверяющий', 'проверивший', 'проверенный', 'проверив', 'тесты', 'Отчёт, ______ (проверить) бухгалтером, отправили директору.'],
  ['организовывать', 'организовать', 'организующий', 'организовавший', 'организованный', 'организовав', 'выставку', 'Концерт, ______ (организовать) студентами, прошёл с успехом.'],
  ['покупать', 'купить', 'покупающий', 'купивший', 'купленный', 'купив', 'билеты', 'Билет, ______ (купить) заранее, стоит дешевле.'],
];
const PART_RULE = [
  (v) => L(`The person is doing it right now - present active participle from imperfective ${v[0]}`, `Человек сам выполняет действие прямо сейчас - действительное причастие настоящего времени от НСВ «${v[0]}»`, `Адам әрекетті дәл қазір өзі орындап жатыр - НСВ «${v[0]}» етістігінен жасалған осы шақтағы действительное причастие`),
  (v) => L(`The person did it and finished it yesterday - past active participle from perfective ${v[1]}`, `Человек сам выполнил действие вчера, оно закончено - действительное причастие прошедшего времени от СВ «${v[1]}»`, `Адам әрекетті кеше өзі орындап бітірді - СВ «${v[1]}» етістігінен жасалған өткен шақтағы действительное причастие`),
  (v) => L(`The thing does not act, something was done to it - past passive participle from ${v[1]}`, `Предмет сам ничего не делает, действие совершили над ним - страдательное причастие прошедшего времени от «${v[1]}»`, `Зат өзі ештеңе істемейді, оған әрекет жасалған - «${v[1]}» етістігінен жасалған өткен шақтағы страдательное причастие`),
  (v) => L(`First one finished action, then another by the same person - perfective gerund from ${v[1]}`, `Сначала одно законченное действие, потом другое у того же человека - деепричастие СВ от «${v[1]}»`, `Алдымен бір аяқталған әрекет, содан кейін сол адамның басқа әрекеті - СВ «${v[1]}» етістігінен жасалған деепричастие`),
];
const partRows = PART.flatMap((v, i) => {
  const forms = v.slice(2, 6);
  const sents = [
    `Студент, ______ (${v[0]}) ${v[6]} в эту минуту, - мой друг.`,
    `Студент, ______ (${v[1]}) ${v[6]} вчера, получил отличную оценку.`,
    v[7],
    `______ (${v[1]}) ${v[6]}, мы решили отдохнуть.`,
  ];
  return sents.map((s, k) => {
    const ok = k === 3 ? cap(forms[3]) : forms[k];
    const cands = forms.filter((_, j) => j !== k).map((f) => (k === 3 ? cap(f) : f));
    return row(5, s, ok, rot(cands, i), why(PART_RULE[k](v), s, ok, DOT));
  });
});

