const prepRows = PREPS.flatMap(([level, prep, c, frame, words], i) =>
  words.map((w, k) => {
    const forms = ABSTRACT_FORMS[w];
    const s = frame.replace('______', `______ (${w})`);
    const ok = forms[c];
    return row(level, s, ok, rot(forms, i + k), L(
      `"${prep}" takes the ${CASE[c].en} case: ${prep} ${ok}. «${full(s, ok)}»`,
      `«${prep}» требует падежа: ${CASE[c].ru} - ${prep} ${ok}. «${full(s, ok)}»`,
      `«${prep}» предлогынан кейін ${CASE[c].kk} керек: ${prep} ${ok}. «${full(s, ok)}»`,
    ));
  }),
);

// ---------- C2: причастие согласуется с определяемым словом ----------
const P_END = {
  m: ['ий', 'его', 'ему', 'его', 'им', 'ем'],
  f: ['ая', 'ей', 'ей', 'ую', 'ей', 'ей'],
  pl: ['ие', 'их', 'им', 'их', 'ими', 'их'],
};
const P_VERB = [['жить', 'живущ', 'в Москве'], ['работать', 'работающ', 'в банке'], ['изучать', 'изучающ', 'русский язык'], ['говорить', 'говорящ', 'на трёх языках'], ['преподавать', 'преподающ', 'в университете'], ['знать', 'знающ', 'китайский язык']];
const P_NOUNS = [['друг', 'm'], ['подруга', 'f'], ['сосед', 'm'], ['сестра', 'f'], ['преподаватель', 'm'], ['друг', 'pl'], ['сосед', 'pl']];
const P_FRAMES = [
  [3, (x, p) => `Я давно знаю ${x}, ${p}.`],
  [2, (x, p) => `Я написал письмо ${x}, ${p}.`],
  [4, (x, p) => `Мы познакомились с ${x}, ${p}.`],
  [5, (x, p) => `Мы много говорили о ${x}, ${p}.`],
  [1, (x, p) => `Это машина ${x}, ${p}.`],
  [0, (x, p) => `${x}, ${p}, приедет к нам завтра.`],
];
const partAgreeRows = P_FRAMES.flatMap(([c, frame], f) =>
  P_NOUNS.map(([w, g], k) => {
    const n = noun(w);
    const nf = g === 'pl' ? n.pl[c] : n.sg[c];
    const [inf, stem, rest] = P_VERB[(f + k) % P_VERB.length];
    const ok = stem + P_END[g][c];
    const cands = rot([...new Set([...P_END[g], ...Object.values(P_END).map((e) => e[c])])].map((e) => stem + e), f + k);
    const subj = c === 0 ? cap(nf) : nf;
    const s = frame(subj, `______ (${inf}) ${rest}`).replace(', приедет', g === 'pl' ? ', приедут' : ', приедет');
    return row(6, s, ok, cands, L(
      `The participle agrees with "${nf}" in gender, number and case (${GENDER[g].en}, ${CASE[c].en}): ${ok}.`,
      `Причастие согласуется со словом «${nf}» в роде, числе и падеже (${GENDER[g].ru}, ${CASE[c].ru} падеж): ${ok}.`,
      `Причастие «${nf}» сөзімен тегі, саны және септігі бойынша қиысады (${GENDER[g].kk}, ${CASE[c].kk}): ${ok}.`,
    ));
  }),
);

